#include <cstdio>
#include <algorithm>

#define FOR(i,e) for(int i=0;i<(int)(e);i++)

using namespace std;

int main(){
    double pb[51][5001];  // Reduced first dimension to 51 to match the maximum `y + 1`
    int x, y, z;
    int v[100], e[51], a[51]; // Adjusted array sizes to match usage

    while(scanf("%d %d %d", &x, &y, &z) == 3 && (x || y || z)){
        FOR(i, x) scanf("%d", &v[i]);
        FOR(i, y + 1) e[i] = a[i] = 0;

        FOR(i, z){
            int n, m, l;
            scanf("%d %d %d", &n, &m, &l);
            e[n] = m; a[n] = l;
        }

        // Initialize the pb array
        FOR(i, y + 1) fill(pb[i], pb[i] + 5001, 0.0); // Efficient initialization
        pb[0][0] = 1.0;

        for (int i = 0; i < y; i++) { // Loop through each state
            for (int j = 0; j < 5001; j++) { // Loop through each value
                if (pb[i][j] > 0.0) { // Only process non-zero states
                    for (int k = 0; k < x; k++) { // Loop through all actions
                        int next = min(y, i + v[k]), value = j;

                        if (e[next] == 1) next = min(y, next + a[next]);
                        else if (e[next] == 2) value += a[next];
                        else if (e[next] == 3) value = max(0, j - a[next]);

                        pb[next][value] += pb[i][j] / x; // Update the probability
                    }
                }
            }
        }

        double ans = 0.0;
        for (int i = 0; i < 5001; i++) ans += pb[y][i] * i;
        printf("%d\n", (int)(ans));
    }
}

