    int x, y, z;
    int v[100], e[51], a[51];

    while(scanf("%d %d %d", &x, &y, &z) == 3 && (x || y || z)){
        FOR(i, x) scanf("%d", &v[i]);
        FOR(i, y + 1) e[i] = a[i] = 0;

        FOR(i, z){
            int n, m, l;
            scanf("%d %d %d", &n, &m, &l);
            e[n] = m; a[n] = l;
        }

